import { useEffect, useMemo, useState } from "react";
import { useLocation } from "wouter";
import { format, isValid, startOfMonth } from "date-fns";
import { trpc } from "@/lib/trpc";
import PageHeader from "@/components/PageHeader";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { toast } from "sonner";
import {
  Bell, CalendarDays, CheckCircle2, ChevronRight, Circle, Columns3, FolderKanban,
  Inbox, LayoutList, ListTodo, Plus, Search, ShieldCheck, Sparkles, Users, X,
  BriefcaseBusiness, Files, CalendarRange, GanttChartSquare, MessageSquare,
} from "lucide-react";
import { cn } from "@/lib/utils";

type HomeTab = "projects" | "my_tasks" | "inbox" | "portfolios";
type ProjectView = "list" | "board" | "timeline" | "calendar" | "overview" | "messages" | "files";

const viewMeta: Record<ProjectView, { label: string; icon: React.ReactNode }> = {
  list: { label: "List", icon: <LayoutList className="h-3.5 w-3.5" /> },
  board: { label: "Board", icon: <Columns3 className="h-3.5 w-3.5" /> },
  timeline: { label: "Timeline", icon: <GanttChartSquare className="h-3.5 w-3.5" /> },
  calendar: { label: "Calendar", icon: <CalendarDays className="h-3.5 w-3.5" /> },
  overview: { label: "Overview", icon: <Sparkles className="h-3.5 w-3.5" /> },
  messages: { label: "Messages", icon: <MessageSquare className="h-3.5 w-3.5" /> },
  files: { label: "Files", icon: <Files className="h-3.5 w-3.5" /> },
};

function asDate(value: unknown) {
  const date = value ? new Date(String(value)) : null;
  return date && isValid(date) ? date : null;
}

function dateInput(value: unknown) {
  const date = asDate(value);
  return date ? format(date, "yyyy-MM-dd") : "";
}

function ProjectCreateDialog({
  open,
  onOpenChange,
  teams,
  onCreated,
}: {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  teams: any[];
  onCreated: (id: number) => void;
}) {
  const [form, setForm] = useState({ name: "", teamId: "", dueOn: "", description: "", defaultView: "list" as ProjectView, privacy: "public_to_team" as const });
  const create = trpc.work.projects.create.useMutation({
    onSuccess: (result) => {
      toast.success("Project created");
      setForm({ name: "", teamId: "", dueOn: "", description: "", defaultView: "list", privacy: "public_to_team" });
      onOpenChange(false);
      onCreated(result.id);
    },
    onError: error => toast.error(error.message),
  });

  function submit(event: React.FormEvent) {
    event.preventDefault();
    if (!form.name.trim()) return toast.error("A project name is required.");
    create.mutate({
      name: form.name.trim(),
      teamId: form.teamId ? Number(form.teamId) : null,
      descriptionPlainText: form.description.trim() || undefined,
      dueOn: form.dueOn ? new Date(`${form.dueOn}T12:00:00`) : null,
      defaultView: form.defaultView,
      privacy: form.privacy,
    });
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-lg">
        <DialogHeader>
          <DialogTitle>Create project</DialogTitle>
          <DialogDescription>Start a project with a flexible task structure, sections, members, and views.</DialogDescription>
        </DialogHeader>
        <form onSubmit={submit} className="space-y-4">
          <div className="space-y-1.5"><Label htmlFor="work-project-name">Project name</Label><Input id="work-project-name" value={form.name} onChange={event => setForm(current => ({ ...current, name: event.target.value }))} autoFocus placeholder="e.g. Listing launch — 123 Maple Street" /></div>
          <div className="space-y-1.5"><Label htmlFor="work-project-description">Description</Label><Textarea id="work-project-description" value={form.description} onChange={event => setForm(current => ({ ...current, description: event.target.value }))} placeholder="What is this project intended to accomplish?" rows={3} /></div>
          <div className="grid grid-cols-1 gap-3 sm:grid-cols-2">
            <div className="space-y-1.5"><Label>Team</Label><Select value={form.teamId || "none"} onValueChange={value => setForm(current => ({ ...current, teamId: value === "none" ? "" : value }))}><SelectTrigger><SelectValue placeholder="No team" /></SelectTrigger><SelectContent><SelectItem value="none">No team</SelectItem>{teams.map(team => <SelectItem key={team.id} value={String(team.id)}>{team.name}</SelectItem>)}</SelectContent></Select></div>
            <div className="space-y-1.5"><Label htmlFor="work-project-due">Target date</Label><Input id="work-project-due" type="date" value={form.dueOn} onChange={event => setForm(current => ({ ...current, dueOn: event.target.value }))} /></div>
            <div className="space-y-1.5"><Label>Default view</Label><Select value={form.defaultView} onValueChange={value => setForm(current => ({ ...current, defaultView: value as ProjectView }))}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent>{Object.entries(viewMeta).map(([value, meta]) => <SelectItem key={value} value={value}>{meta.label}</SelectItem>)}</SelectContent></Select></div>
            <div className="space-y-1.5"><Label>Privacy</Label><Select value={form.privacy} onValueChange={value => setForm(current => ({ ...current, privacy: value as typeof form.privacy }))}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectItem value="public_to_team">Team members</SelectItem><SelectItem value="private_to_members">Only invited members</SelectItem><SelectItem value="public_to_workspace">Entire workspace</SelectItem></SelectContent></Select></div>
          </div>
          <DialogFooter><Button type="button" variant="outline" onClick={() => onOpenChange(false)}>Cancel</Button><Button type="submit" disabled={create.isPending}>{create.isPending ? "Creating…" : "Create project"}</Button></DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

function TeamCreateDialog({ open, onOpenChange, onCreated }: { open: boolean; onOpenChange: (open: boolean) => void; onCreated: () => void }) {
  const [name, setName] = useState("");
  const create = trpc.work.teams.create.useMutation({
    onSuccess: () => { toast.success("Team created"); setName(""); onOpenChange(false); onCreated(); },
    onError: error => toast.error(error.message),
  });
  return <Dialog open={open} onOpenChange={onOpenChange}><DialogContent className="sm:max-w-md"><DialogHeader><DialogTitle>Create team</DialogTitle><DialogDescription>Teams organize the projects they own and their membership.</DialogDescription></DialogHeader><form onSubmit={event => { event.preventDefault(); if (name.trim()) create.mutate({ name: name.trim() }); }} className="space-y-4"><div className="space-y-1.5"><Label htmlFor="work-team-name">Team name</Label><Input id="work-team-name" value={name} onChange={event => setName(event.target.value)} placeholder="e.g. Marketing" autoFocus /></div><DialogFooter><Button type="button" variant="outline" onClick={() => onOpenChange(false)}>Cancel</Button><Button type="submit" disabled={!name.trim() || create.isPending}>{create.isPending ? "Creating…" : "Create team"}</Button></DialogFooter></form></DialogContent></Dialog>;
}

function AddTaskForm({ projectId, sectionId, onDone }: { projectId: number; sectionId: number | null; onDone: () => void }) {
  const [name, setName] = useState("");
  const [dueOn, setDueOn] = useState("");
  const create = trpc.work.tasks.create.useMutation({
    onSuccess: () => { setName(""); setDueOn(""); onDone(); },
    onError: error => toast.error(error.message),
  });
  return <form className="flex items-center gap-2 border-t border-border bg-muted/20 px-3 py-2" onSubmit={event => { event.preventDefault(); if (name.trim()) create.mutate({ name: name.trim(), projectId, sectionId, dueOn: dueOn ? new Date(`${dueOn}T12:00:00`) : null }); }}><Input value={name} onChange={event => setName(event.target.value)} placeholder="Add a task…" className="h-8 text-sm" /><Input value={dueOn} onChange={event => setDueOn(event.target.value)} type="date" className="h-8 w-36 text-xs" /><Button size="sm" type="submit" disabled={!name.trim() || create.isPending}><Plus className="mr-1 h-3.5 w-3.5" />Add</Button></form>;
}

function TaskRow({ task, onSelect, onRefresh }: { task: any; onSelect: (task: any) => void; onRefresh: () => void }) {
  const complete = trpc.work.tasks.complete.useMutation({ onSuccess: onRefresh, onError: error => toast.error(error.message) });
  const date = asDate(task.dueOn ?? task.dueAt);
  return <div className="group flex cursor-pointer items-center gap-2 border-t border-border px-3 py-2.5 hover:bg-muted/50" onClick={() => onSelect(task)}>
    <button aria-label={task.completionStatus === "complete" ? "Reopen task" : "Complete task"} onClick={event => { event.stopPropagation(); complete.mutate({ id: task.id, completed: task.completionStatus !== "complete" }); }} className="shrink-0 text-muted-foreground hover:text-primary">{task.completionStatus === "complete" ? <CheckCircle2 className="h-4 w-4 text-emerald-600" /> : <Circle className="h-4 w-4" />}</button>
    <span className={cn("min-w-0 flex-1 truncate text-sm", task.completionStatus === "complete" && "text-muted-foreground line-through")}>{task.name}</span>
    {task.taskType === "milestone" && <Badge variant="outline" className="text-[10px]">Milestone</Badge>}
    {task.assignees?.length > 0 && <span title={task.assignees.map((assignee: any) => assignee.name).join(", ")} className="hidden max-w-28 truncate text-xs text-muted-foreground md:block">{task.assignees.map((assignee: any) => assignee.name?.split(" ")[0]).join(", ")}</span>}
    {date && <span className="w-20 shrink-0 text-right text-xs text-muted-foreground">{format(date, "MMM d")}</span>}
  </div>;
}

function TaskDetailDialog({ task, open, onOpenChange, onRefresh }: { task: any; open: boolean; onOpenChange: (open: boolean) => void; onRefresh: () => void }) {
  const taskQuery = trpc.work.tasks.get.useQuery({ id: task?.id ?? 0 }, { enabled: !!task?.id && open });
  const current = taskQuery.data as any;
  const taskFieldProjectId = current?.memberships?.[0]?.projectId ?? 0;
  const taskFieldsQuery = trpc.work.customFields.listForProject.useQuery({ projectId: taskFieldProjectId }, { enabled: !!taskFieldProjectId && open });
  const [comment, setComment] = useState("");
  const [descriptionDraft, setDescriptionDraft] = useState("");
  const [newTag, setNewTag] = useState("");
  const [newSubtask, setNewSubtask] = useState("");
  const addComment = trpc.work.tasks.addComment.useMutation({ onSuccess: () => { setComment(""); taskQuery.refetch(); onRefresh(); }, onError: error => toast.error(error.message) });
  const updateTask = trpc.work.tasks.update.useMutation({ onSuccess: () => { taskQuery.refetch(); onRefresh(); toast.success("Task updated"); }, onError: error => toast.error(error.message) });
  const completeTask = trpc.work.tasks.complete.useMutation({ onSuccess: () => { taskQuery.refetch(); onRefresh(); }, onError: error => toast.error(error.message) });
  const removeFromProject = trpc.work.tasks.removeFromProject.useMutation({ onSuccess: () => { taskQuery.refetch(); onRefresh(); toast.success("Task removed from project"); }, onError: error => toast.error(error.message) });
  const tagsQuery = trpc.work.tags.list.useQuery();
  const setTags = trpc.work.tasks.setTags.useMutation({ onSuccess: () => { taskQuery.refetch(); onRefresh(); }, onError: error => toast.error(error.message) });
  const createTag = trpc.work.tags.create.useMutation({ onSuccess: (result) => { if (current?.id) setTags.mutate({ taskId: current.id, tagIds: [...(current.tags ?? []).map((item: any) => item.id), result.id] }); setNewTag(""); tagsQuery.refetch(); }, onError: error => toast.error(error.message) });
  const createSubtask = trpc.work.tasks.create.useMutation({ onSuccess: () => { setNewSubtask(""); taskQuery.refetch(); onRefresh(); }, onError: error => toast.error(error.message) });
  useEffect(() => { if (current?.id) setDescriptionDraft(current.descriptionPlainText ?? ""); }, [current?.id, current?.descriptionPlainText]);
  if (!open) return null;
  return <aside role="dialog" aria-modal="false" className="fixed inset-y-0 right-0 z-40 w-full max-w-[480px] overflow-y-auto border-l border-border bg-background p-5 shadow-2xl sm:w-[480px]"><div className="relative"><Button type="button" variant="ghost" size="icon" aria-label="Close task details" onClick={() => onOpenChange(false)} className="absolute right-0 top-0"><X className="h-4 w-4" /></Button><header className="pr-10"><h2 className="pr-8 text-lg font-semibold">{current?.name ?? task?.name ?? "Task"}</h2><div className="mt-2 flex flex-wrap gap-1">{current?.memberships?.length ? current.memberships.map((membership: any) => <Badge key={membership.projectId} variant="secondary" className="gap-1"><span>{membership.projectName}</span><button type="button" aria-label={`Remove from ${membership.projectName}`} onClick={() => removeFromProject.mutate({ taskId: current.id, projectId: membership.projectId })} className="rounded-sm hover:bg-muted-foreground/15"><X className="h-3 w-3" /></button></Badge>) : <span className="text-sm text-muted-foreground">Personal task</span>}</div></header>{!current ? <div className="py-12 text-center text-sm text-muted-foreground">Loading task…</div> : <div className="space-y-5"><div className="grid grid-cols-2 gap-3 rounded-lg border border-border bg-muted/20 p-3 text-sm sm:grid-cols-4"><div><p className="text-xs text-muted-foreground">Status</p><Button variant="ghost" size="sm" className="h-6 px-0 font-medium capitalize" onClick={() => completeTask.mutate({ id: current.id, completed: current.completionStatus !== "complete" })}>{current.completionStatus === "complete" ? "Reopen" : "Complete"}</Button></div><div><p className="text-xs text-muted-foreground">Due</p><Input type="date" className="h-7 px-1 text-xs" value={current.dueOn ? new Date(current.dueOn).toISOString().slice(0, 10) : ""} onChange={event => updateTask.mutate({ id: current.id, dueOn: event.target.value || null })} /></div><div><p className="text-xs text-muted-foreground">Assignees</p><p className="font-medium">{current.assignees?.map((assignee: any) => assignee.name).filter(Boolean).join(", ") || "None"}</p></div><div><p className="text-xs text-muted-foreground">Followers</p><p className="font-medium">{current.followers?.length ?? 0}</p></div></div><div><p className="mb-2 text-xs font-medium uppercase tracking-wide text-muted-foreground">Tags</p><div className="flex flex-wrap gap-1">{(tagsQuery.data as any[] ?? []).length ? (tagsQuery.data as any[]).map(tag => { const selected = current.tags?.some((item: any) => item.id === tag.id); return <button key={tag.id} type="button" onClick={() => setTags.mutate({ taskId: current.id, tagIds: selected ? current.tags.filter((item: any) => item.id !== tag.id).map((item: any) => item.id) : [...(current.tags ?? []).map((item: any) => item.id), tag.id] })} className={cn("rounded-full border px-2 py-0.5 text-xs", selected ? "border-primary bg-primary/10" : "border-border hover:bg-muted")} style={tag.color ? { borderColor: selected ? tag.color : undefined } : undefined}>{tag.name}</button>; }) : <div className="flex w-full gap-2"><Input className="h-7 text-xs" value={newTag} onChange={event => setNewTag(event.target.value)} placeholder="Create a tag…" onKeyDown={event => { if (event.key === "Enter" && newTag.trim()) { event.preventDefault(); createTag.mutate({ name: newTag.trim() }); } }} /><Button size="sm" className="h-7" disabled={!newTag.trim() || createTag.isPending} onClick={() => createTag.mutate({ name: newTag.trim() })}>Add</Button></div>}</div></div><div><p className="mb-2 text-xs font-medium uppercase tracking-wide text-muted-foreground">Subtasks</p><div className="space-y-1">{current.subtasks?.map((subtask: any) => <div key={subtask.id} className="flex items-center justify-between rounded border border-border px-2 py-1 text-sm"><span className={cn(subtask.completionStatus === "complete" && "line-through text-muted-foreground")}>{subtask.name}</span><span className="text-xs text-muted-foreground">{subtask.completionStatus}</span></div>)}</div><form className="mt-2 flex gap-2" onSubmit={event => { event.preventDefault(); const projectId = current.memberships?.[0]?.projectId; if (newSubtask.trim() && projectId) createSubtask.mutate({ name: newSubtask.trim(), projectId, parentTaskId: current.id }); }}><Input className="h-8 text-xs" value={newSubtask} onChange={event => setNewSubtask(event.target.value)} placeholder="Add subtask…" /><Button size="sm" type="submit" disabled={!newSubtask.trim() || !current.memberships?.[0]?.projectId || createSubtask.isPending}>Add</Button></form></div>{(taskFieldsQuery.data as any[] ?? []).length > 0 && <div><p className="mb-2 text-xs font-medium uppercase tracking-wide text-muted-foreground">Project fields</p><div className="space-y-2">{(taskFieldsQuery.data as any[]).map(field => { const existing = current.customValues?.find((value: any) => value.customFieldId === field.customFieldId); const rawValue = existing?.value ?? ""; if (field.fieldType === "boolean") return <label key={field.customFieldId} className="flex items-center gap-2 text-sm"><input type="checkbox" checked={Boolean(rawValue)} onChange={event => updateTask.mutate({ id: current.id, customFieldValues: [{ customFieldId: field.customFieldId, value: event.target.checked, plainTextValue: String(event.target.checked) }] })} />{field.name}</label>; return <label key={field.customFieldId} className="block text-xs text-muted-foreground">{field.name}<Input type={field.fieldType === "number" ? "number" : field.fieldType === "date" ? "date" : field.fieldType === "url" ? "url" : "text"} defaultValue={typeof rawValue === "string" || typeof rawValue === "number" ? String(rawValue) : ""} className="mt-1 h-8 text-sm text-foreground" onBlur={event => { const value = field.fieldType === "number" && event.target.value !== "" ? Number(event.target.value) : event.target.value; if (JSON.stringify(value) !== JSON.stringify(rawValue)) updateTask.mutate({ id: current.id, customFieldValues: [{ customFieldId: field.customFieldId, value, plainTextValue: String(value) }] }); }} /></label>; })}</div></div>}<div><div className="mb-1 flex items-center justify-between"><p className="text-xs font-medium uppercase tracking-wide text-muted-foreground">Description</p><Button size="sm" variant="ghost" disabled={updateTask.isPending || descriptionDraft === (current.descriptionPlainText ?? "")} onClick={() => updateTask.mutate({ id: current.id, descriptionPlainText: descriptionDraft || null })}>Save</Button></div><Textarea value={descriptionDraft} onChange={event => setDescriptionDraft(event.target.value)} placeholder="Add a task description…" className="min-h-24 text-sm" /></div><div><p className="mb-2 text-xs font-medium uppercase tracking-wide text-muted-foreground">Activity</p><div className="space-y-3">{current.stories?.length ? current.stories.map((story: any) => <div key={story.id} className="border-l-2 border-primary/25 pl-3"><p className="text-sm">{story.contentPlainText || story.storyType}</p><p className="text-xs text-muted-foreground">{story.actorName || "SavvyOS"} · {format(new Date(story.createdAt), "MMM d, h:mm a")}</p></div>) : <p className="text-sm text-muted-foreground">No activity yet.</p>}</div></div><form onSubmit={event => { event.preventDefault(); if (comment.trim()) addComment.mutate({ taskId: current.id, contentPlainText: comment.trim() }); }} className="flex gap-2"><Input value={comment} onChange={event => setComment(event.target.value)} placeholder="Add a comment…" /><Button type="submit" disabled={!comment.trim() || addComment.isPending}><MessageSquare className="mr-1 h-3.5 w-3.5" />Post</Button></form></div>}</div></aside>;
}

function ProjectWorkspace({ projectId, onRefresh }: { projectId: number; onRefresh: () => void }) {
  const [location, navigate] = useLocation();
  const projectQuery = trpc.work.projects.get.useQuery({ id: projectId }, { enabled: !!projectId });
  const routeView = (location.match(/^\/work\/projects\/\d+\/(list|board|timeline|calendar|overview|messages|files)/)?.[1] ?? null) as ProjectView | null;
  const taskRouteId = Number(location.match(/^\/work\/projects\/\d+\/tasks\/(\d+)/)?.[1] ?? 0) || null;
  const [view, setView] = useState<ProjectView>(routeView ?? "list");
  const [selectedTask, setSelectedTask] = useState<any>(null);
  const data = projectQuery.data as any;
  const tasksQuery = trpc.work.tasks.listForProject.useQuery({ projectId, limit: 100 }, { enabled: !!projectId });
  const projectFieldsQuery = trpc.work.customFields.listForProject.useQuery({ projectId }, { enabled: !!projectId });
  const allFieldsQuery = trpc.work.customFields.list.useQuery();
  const projectFields = (projectFieldsQuery.data as any[]) ?? [];
  const tasks = (tasksQuery.data as any)?.items ?? [];
  const openTask = (task: any) => { setSelectedTask(task); navigate(`/work/projects/${projectId}/tasks/${task.id}`); };
  useEffect(() => {
    if (!taskRouteId) return;
    const routedTask = tasks.find((task: any) => task.id === taskRouteId);
    if (routedTask) setSelectedTask(routedTask);
  }, [taskRouteId, tasks]);
  useEffect(() => {
    if (routeView) { setView(routeView); return; }
    if (data?.defaultView) {
      setView(data.defaultView as ProjectView);
      if (!taskRouteId) navigate(`/work/projects/${projectId}/${data.defaultView}`, { replace: true });
    }
  }, [data?.defaultView, navigate, projectId, routeView, taskRouteId]);
  const sections = data?.sections ?? [];
  const tasksBySection = useMemo(() => {
    const map = new Map<number | null, any[]>();
    for (const task of tasks) map.set(task.sectionId ?? null, [...(map.get(task.sectionId ?? null) ?? []), task]);
    return map;
  }, [tasks]);
  const addSection = trpc.work.sections.create.useMutation({ onSuccess: () => projectQuery.refetch(), onError: error => toast.error(error.message) });
  const updateSection = trpc.work.sections.update.useMutation({ onSuccess: () => projectQuery.refetch(), onError: error => toast.error(error.message) });
  const [showSectionInput, setShowSectionInput] = useState(false);
  const [sectionName, setSectionName] = useState("");
  const [statusTitle, setStatusTitle] = useState("");
  const [fieldName, setFieldName] = useState("");
  const [fieldType, setFieldType] = useState("text");
  const [statusBody, setStatusBody] = useState("");
  const [savedViewName, setSavedViewName] = useState("");
  const savedViewsQuery = trpc.work.savedViews.list.useQuery({ projectId }, { enabled: !!projectId });
  const rulesQuery = trpc.work.rules.list.useQuery({ projectId }, { enabled: !!projectId });
  const setRuleActive = trpc.work.rules.setActive.useMutation({ onSuccess: () => { rulesQuery.refetch(); toast.success("Rule updated"); }, onError: error => toast.error(error.message) });
  const createSavedView = trpc.work.savedViews.create.useMutation({ onSuccess: () => { setSavedViewName(""); savedViewsQuery.refetch(); toast.success("View saved"); }, onError: error => toast.error(error.message) });
  const createStatusUpdate = trpc.work.statusUpdates.create.useMutation({ onSuccess: () => { setStatusTitle(""); setStatusBody(""); projectQuery.refetch(); toast.success("Status update posted"); }, onError: error => toast.error(error.message) });
  const attachField = trpc.work.customFields.addToProject.useMutation({ onSuccess: () => projectFieldsQuery.refetch(), onError: error => toast.error(error.message) });
  const createField = trpc.work.customFields.create.useMutation({ onSuccess: result => { attachField.mutate({ projectId: data.id, customFieldId: result.id }); setFieldName(""); allFieldsQuery.refetch(); }, onError: error => toast.error(error.message) });
  const refresh = () => { projectQuery.refetch(); tasksQuery.refetch(); onRefresh(); };
  const completed = tasks.filter((task: any) => task.completionStatus === "complete").length;
  const datedTasks = tasks.filter((task: any) => task.dueOn || task.dueAt).sort((a: any, b: any) => (String(a.dueOn ?? a.dueAt)).localeCompare(String(b.dueOn ?? b.dueAt)));
  return <main className="min-h-full w-full bg-background"><div className="sticky top-0 z-10 border-b border-border bg-card px-5 py-4"><header><div className="flex items-start justify-between gap-6"><div className="min-w-0"><h1 className="flex items-center gap-2 text-xl font-semibold"><span className="h-3 w-3 rounded-full" style={{ backgroundColor: data?.color || "#14b8a6" }} />{data?.name || "Loading project…"}</h1><p className="mt-1 text-sm text-muted-foreground">{data?.teamName || "No team"}{data?.ownerName ? ` · Owner: ${data.ownerName}` : ""}</p></div><div className="hidden items-center gap-3 text-right sm:flex"><div><p className="text-xs text-muted-foreground">Progress</p><p className="text-sm font-semibold">{completed}/{tasks.length} complete</p></div><div className="h-2 w-24 overflow-hidden rounded-full bg-muted"><div className="h-full bg-primary" style={{ width: `${tasks.length ? Math.round((completed / tasks.length) * 100) : 0}%` }} /></div></div></div></header></div>{data && <div className="p-5"><Tabs value={view} onValueChange={value => navigate(`/work/projects/${projectId}/${value}`)}><TabsList className="mb-5 h-auto w-full justify-start overflow-x-auto bg-transparent p-0"><div className="flex gap-1">{(Object.keys(viewMeta) as ProjectView[]).map(key => <TabsTrigger key={key} value={key} className="gap-1.5 data-[state=active]:bg-muted">{viewMeta[key].icon}{viewMeta[key].label}</TabsTrigger>)}</div></TabsList><TabsContent value="list" className="mt-0"><div className="space-y-3">{sections.map((section: any) => <div key={section.id} className="overflow-hidden rounded-lg border border-border"><div className="flex items-center justify-between bg-muted/35 px-3 py-2"><Input defaultValue={section.name} aria-label={`Section name ${section.name}`} className="h-7 max-w-xs border-0 bg-transparent px-0 text-sm font-semibold shadow-none focus-visible:ring-0" onBlur={event => { const name = event.target.value.trim(); if (name && name !== section.name) updateSection.mutate({ id: section.id, name }); }} /><span className="text-xs text-muted-foreground">{(tasksBySection.get(section.id) ?? []).length}</span></div>{(tasksBySection.get(section.id) ?? []).map(task => <TaskRow key={task.id} task={task} onSelect={openTask} onRefresh={refresh} />)}<AddTaskForm projectId={data.id} sectionId={section.id} onDone={refresh} /></div>)}{(tasksBySection.get(null) ?? []).length > 0 && <div className="overflow-hidden rounded-lg border border-border"><div className="bg-muted/35 px-3 py-2 text-sm font-semibold">Unsectioned</div>{(tasksBySection.get(null) ?? []).map(task => <TaskRow key={task.id} task={task} onSelect={openTask} onRefresh={refresh} />)}</div>}{showSectionInput ? <form onSubmit={event => { event.preventDefault(); if (sectionName.trim()) addSection.mutate({ projectId: data.id, name: sectionName.trim() }, { onSuccess: () => { setSectionName(""); setShowSectionInput(false); } }); }} className="flex gap-2"><Input value={sectionName} onChange={event => setSectionName(event.target.value)} placeholder="Section name" autoFocus /><Button type="submit">Add section</Button><Button type="button" variant="outline" onClick={() => setShowSectionInput(false)}>Cancel</Button></form> : <Button variant="outline" size="sm" onClick={() => setShowSectionInput(true)}><Plus className="mr-1 h-3.5 w-3.5" />Add section</Button>}</div></TabsContent><TabsContent value="board" className="mt-0"><div className="grid min-w-max grid-cols-[repeat(auto-fit,minmax(250px,1fr))] gap-4">{sections.map((section: any) => <div key={section.id} className="w-72 rounded-lg border border-border bg-muted/20 p-3"><p className="mb-3 text-sm font-semibold">{section.name}<span className="ml-2 text-xs font-normal text-muted-foreground">{(tasksBySection.get(section.id) ?? []).length}</span></p><div className="space-y-2">{(tasksBySection.get(section.id) ?? []).map(task => <button key={task.id} className="w-full rounded-md border border-border bg-card p-3 text-left shadow-sm hover:border-primary/50" onClick={() => openTask(task)}><p className={cn("text-sm font-medium", task.completionStatus === "complete" && "line-through text-muted-foreground")}>{task.name}</p>{task.dueOn && <p className="mt-1 text-xs text-muted-foreground">Due {format(new Date(task.dueOn), "MMM d")}</p>}</button>)}</div><div className="mt-3"><AddTaskForm projectId={data.id} sectionId={section.id} onDone={refresh} /></div></div>)}</div></TabsContent><TabsContent value="timeline" className="mt-0"><div className="rounded-lg border border-border"><div className="border-b border-border bg-muted/30 px-4 py-3 text-sm font-semibold">Timeline</div>{datedTasks.length ? datedTasks.map((task: any) => <div key={task.id} className="grid grid-cols-[120px_1fr] border-b border-border last:border-0"><div className="border-r border-border px-3 py-3 text-xs text-muted-foreground">{format(new Date(task.dueOn ?? task.dueAt), "MMM d, yyyy")}</div><button onClick={() => openTask(task)} className="px-3 py-3 text-left text-sm hover:bg-muted/50">{task.name}</button></div>) : <p className="p-8 text-center text-sm text-muted-foreground">Give tasks a start or due date to display them on the timeline.</p>}</div></TabsContent><TabsContent value="calendar" className="mt-0"><div className="rounded-lg border border-border"><div className="border-b border-border bg-muted/30 px-4 py-3 text-sm font-semibold">{format(startOfMonth(new Date()), "MMMM yyyy")}</div>{datedTasks.length ? <div className="grid grid-cols-1 gap-2 p-4 sm:grid-cols-2 lg:grid-cols-3">{datedTasks.map((task: any) => <button key={task.id} onClick={() => openTask(task)} className="rounded-md border border-border p-3 text-left hover:border-primary/50"><p className="text-xs text-muted-foreground">{format(new Date(task.dueOn ?? task.dueAt), "EEE, MMM d")}</p><p className="mt-1 text-sm font-medium">{task.name}</p></button>)}</div> : <p className="p-8 text-center text-sm text-muted-foreground">No dated tasks yet.</p>}</div></TabsContent><TabsContent value="overview" className="mt-0"><div className="grid gap-4 lg:grid-cols-3"><div className="rounded-lg border border-border p-4 lg:col-span-2"><h3 className="font-semibold">Project overview</h3><p className="mt-2 whitespace-pre-wrap text-sm text-muted-foreground">{data.descriptionPlainText || "Add a project description to orient the team."}</p><div className="mt-5 grid grid-cols-3 gap-3"><div className="rounded-md bg-muted/40 p-3"><p className="text-xl font-bold">{tasks.length}</p><p className="text-xs text-muted-foreground">Tasks</p></div><div className="rounded-md bg-muted/40 p-3"><p className="text-xl font-bold">{completed}</p><p className="text-xs text-muted-foreground">Completed</p></div><div className="rounded-md bg-muted/40 p-3"><p className="text-xl font-bold">{data.members?.length ?? 0}</p><p className="text-xs text-muted-foreground">Members</p></div></div></div><div className="rounded-lg border border-border p-4"><h3 className="font-semibold">Project fields</h3>{projectFields.length ? <div className="mt-3 space-y-2">{projectFields.map((field: any) => <div key={field.customFieldId} className="flex items-center justify-between text-sm"><span>{field.name}</span><Badge variant="outline" className="text-[10px]">{field.fieldType}</Badge></div>)}</div> : <p className="mt-2 text-sm text-muted-foreground">No fields attached yet.</p>}<div className="mt-3 flex gap-2"><Input className="h-8 text-xs" value={fieldName} onChange={event => setFieldName(event.target.value)} placeholder="New field name" /><select aria-label="Field type" value={fieldType} onChange={event => setFieldType(event.target.value)} className="h-8 rounded-md border border-input bg-background px-2 text-xs"><option value="text">Text</option><option value="number">Number</option><option value="date">Date</option><option value="boolean">Checkbox</option><option value="url">URL</option></select><Button size="sm" disabled={!fieldName.trim() || createField.isPending} onClick={() => createField.mutate({ name: fieldName.trim(), fieldType: fieldType as any })}>Add</Button></div></div><div className="rounded-lg border border-border p-4"><h3 className="font-semibold">Status updates</h3>{data.statusUpdates?.length ? data.statusUpdates.map((update: any) => <div className="mt-3 border-l-2 border-primary pl-3" key={update.id}><p className="text-sm font-medium capitalize">{String(update.status).replace("_", " ")}</p><p className="text-xs text-muted-foreground">{format(new Date(update.createdAt), "MMM d")}</p><p className="mt-1 text-sm">{update.bodyPlainText || update.title}</p></div>) : <p className="mt-2 text-sm text-muted-foreground">No status updates yet.</p>}<div className="mt-4 space-y-2 border-t border-border pt-3"><Input value={statusTitle} onChange={event => setStatusTitle(event.target.value)} placeholder="Status update title" className="h-8 text-xs" /><Textarea value={statusBody} onChange={event => setStatusBody(event.target.value)} placeholder="Share a concise project update…" className="min-h-16 text-xs" /><Button size="sm" disabled={!statusTitle.trim() || createStatusUpdate.isPending} onClick={() => createStatusUpdate.mutate({ projectId: data.id, status: "on_track", title: statusTitle.trim(), bodyPlainText: statusBody.trim() || undefined })}>Post update</Button></div></div></div><div className="mt-4 rounded-lg border border-border p-4"><h3 className="font-semibold">Automation rules</h3><p className="mt-1 text-xs text-muted-foreground">Review and pause project rules without losing their configuration.</p>{(rulesQuery.data as any[] ?? []).length ? <div className="mt-3 space-y-2">{(rulesQuery.data as any[]).map((rule: any) => <div key={rule.id} className="flex items-center justify-between rounded border border-border px-3 py-2"><div><p className="text-sm font-medium">{rule.name}</p><p className="text-xs text-muted-foreground">{String(rule.trigger).replaceAll("_", " ")} · {rule.actions?.length ?? 0} actions</p></div><Button variant="outline" size="sm" disabled={setRuleActive.isPending} onClick={() => setRuleActive.mutate({ id: rule.id, isActive: !rule.isActive })}>{rule.isActive ? "Pause" : "Enable"}</Button></div>)}</div> : <p className="mt-3 text-sm text-muted-foreground">No project rules configured yet.</p>}</div><div className="mt-4 rounded-lg border border-border p-4"><h3 className="font-semibold">Saved views</h3><p className="mt-1 text-xs text-muted-foreground">Save the current project view for quick reuse.</p><div className="mt-3 flex flex-wrap gap-2"><Input className="h-8 min-w-48 flex-1 text-xs" value={savedViewName} onChange={event => setSavedViewName(event.target.value)} placeholder={`Save ${viewMeta[view].label} view as…`} /><Button size="sm" disabled={!savedViewName.trim() || createSavedView.isPending} onClick={() => createSavedView.mutate({ projectId: data.id, name: savedViewName.trim(), viewType: view, filters: {}, config: { view } })}>Save view</Button></div>{(savedViewsQuery.data as any[] ?? []).length ? <div className="mt-3 flex flex-wrap gap-2">{(savedViewsQuery.data as any[]).map((saved: any) => <Button key={saved.id} variant="outline" size="sm" onClick={() => navigate(`/work/projects/${projectId}/${saved.viewType}`)}>{saved.name}</Button>)}</div> : null}</div></TabsContent><TabsContent value="messages" className="mt-0"><MessagesView projectId={data.id} /></TabsContent><TabsContent value="files" className="mt-0"><FilesView projectId={data.id} /></TabsContent></Tabs></div>}<TaskDetailDialog task={selectedTask} open={!!selectedTask} onOpenChange={value => { if (!value) { setSelectedTask(null); navigate(`/work/projects/${projectId}/${view}`); } }} onRefresh={refresh} /></main>;
}

function MessagesView({ projectId }: { projectId: number }) {
  const messagesQuery = trpc.work.projects.listMessages.useQuery({ projectId });
  const [subject, setSubject] = useState("");
  const [message, setMessage] = useState("");
  const addMessage = trpc.work.projects.addMessage.useMutation({
    onSuccess: () => { setSubject(""); setMessage(""); messagesQuery.refetch(); },
    onError: error => toast.error(error.message),
  });
  const messages = (messagesQuery.data as any[]) ?? [];
  return <div className="grid gap-4 lg:grid-cols-[minmax(0,1fr)_300px]"><section className="rounded-lg border border-border"><div className="border-b border-border px-4 py-3"><h3 className="font-semibold">Project messages</h3><p className="text-xs text-muted-foreground">A shared discussion stream separate from task comments.</p></div><div className="max-h-[420px] space-y-4 overflow-y-auto p-4">{messages.length ? messages.map(item => { const metadata = (item.metadata ?? {}) as Record<string, unknown>; return <article key={item.id} className="border-l-2 border-primary/30 pl-3"><p className="text-sm font-medium">{typeof metadata.subject === "string" && metadata.subject ? metadata.subject : "Project message"}</p><p className="mt-1 whitespace-pre-wrap text-sm">{item.contentPlainText}</p><p className="mt-2 text-xs text-muted-foreground">{item.actorName || "SavvyOS"} · {format(new Date(item.createdAt), "MMM d, h:mm a")}</p></article>; }) : <p className="py-10 text-center text-sm text-muted-foreground">No project messages yet.</p>}</div></section><form className="space-y-3 rounded-lg border border-border p-4" onSubmit={event => { event.preventDefault(); if (message.trim()) addMessage.mutate({ projectId, subject: subject.trim() || undefined, contentPlainText: message.trim() }); }}><h3 className="font-semibold">Start a conversation</h3><Input value={subject} onChange={event => setSubject(event.target.value)} placeholder="Subject (optional)" /><Textarea value={message} onChange={event => setMessage(event.target.value)} placeholder="Write a message…" className="min-h-28" /><Button type="submit" disabled={!message.trim() || addMessage.isPending}><MessageSquare className="mr-1.5 h-4 w-4" />Post message</Button></form></div>;
}

function FilesView({ projectId }: { projectId: number }) {
  const { data = [] } = trpc.work.attachments.listForProject.useQuery({ projectId });
  return <div className="rounded-lg border border-border p-5">{(data as any[]).length ? <div className="space-y-2">{(data as any[]).map(file => <a className="flex items-center justify-between rounded-md border border-border px-3 py-2 text-sm hover:bg-muted" key={file.id} href={file.fileUrl} target="_blank" rel="noreferrer"><span className="truncate">{file.fileName}</span><span className="text-xs text-muted-foreground">{format(new Date(file.createdAt), "MMM d")}</span></a>)}</div> : <div className="py-8 text-center"><Files className="mx-auto mb-2 h-7 w-7 text-muted-foreground" /><p className="text-sm text-muted-foreground">No files are attached to this project.</p></div>}</div>;
}

export default function WorkManagementPage() {
  const [location, navigate] = useLocation();
  const projectRouteId = Number(location.match(/^\/work\/projects\/(\d+)/)?.[1] ?? 0) || null;
  const taskRouteId = Number(location.match(/^\/work\/tasks\/(\d+)/)?.[1] ?? 0) || null;
  const homeTab: HomeTab = location.startsWith("/work/my-tasks") ? "my_tasks" : location.startsWith("/work/inbox") ? "inbox" : location.startsWith("/work/portfolios") ? "portfolios" : "projects";
  const [search, setSearch] = useState("");
  const [projectDialog, setProjectDialog] = useState(false);
  const [teamDialog, setTeamDialog] = useState(false);
  const [globalSearchOpen, setGlobalSearchOpen] = useState(false);
  const [globalSearch, setGlobalSearch] = useState("");
  const projectsQuery = trpc.work.projects.list.useQuery({ search: search || undefined, limit: 100 });
  const teamsQuery = trpc.work.teams.list.useQuery();
  const myTasksQuery = trpc.work.myTasks.list.useQuery({ limit: 100 }, { enabled: homeTab === "my_tasks" });
  const delegatedTasksQuery = trpc.work.myTasks.assignedToOthers.useQuery({ limit: 100 }, { enabled: homeTab === "my_tasks" });
  const inboxQuery = trpc.work.inbox.list.useQuery({ limit: 100 }, { enabled: homeTab === "inbox" });
  const portfoliosQuery = trpc.work.portfolios.list.useQuery(undefined, { enabled: homeTab === "portfolios" });
  const globalResultsQuery = trpc.work.search.useQuery({ query: globalSearch || "_", limit: 15 }, { enabled: globalSearchOpen && globalSearch.trim().length > 1 });
  const markRead = trpc.work.inbox.markRead.useMutation({ onSuccess: () => inboxQuery.refetch(), onError: error => toast.error(error.message) });
  const createPortfolio = trpc.work.portfolios.create.useMutation({ onSuccess: () => { toast.success("Portfolio created"); portfoliosQuery.refetch(); }, onError: error => toast.error(error.message) });
  const [newPortfolio, setNewPortfolio] = useState("");
  const [showDelegated, setShowDelegated] = useState(false);
  const [selectedPortfolioId, setSelectedPortfolioId] = useState<number | null>(null);
  const [portfolioProjectId, setPortfolioProjectId] = useState("");
  const portfolioItemsQuery = trpc.work.portfolios.items.useQuery({ portfolioId: selectedPortfolioId ?? 0 }, { enabled: !!selectedPortfolioId });
  const addPortfolioProject = trpc.work.portfolios.addProject.useMutation({ onSuccess: () => { setPortfolioProjectId(""); portfolioItemsQuery.refetch(); toast.success("Project added to portfolio"); }, onError: error => toast.error(error.message) });
  const removePortfolioItem = trpc.work.portfolios.removeItem.useMutation({ onSuccess: () => { portfolioItemsQuery.refetch(); toast.success("Portfolio item removed"); }, onError: error => toast.error(error.message) });

  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === "k") { event.preventDefault(); setGlobalSearchOpen(true); }
      if (event.altKey && event.key.toLowerCase() === "q") { event.preventDefault(); setProjectDialog(true); }
    };
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, []);

  const projects = (projectsQuery.data as any)?.items ?? [];
  const visibleMyTasks = ((showDelegated ? delegatedTasksQuery.data : myTasksQuery.data) as any)?.items ?? [];
  const unread = ((inboxQuery.data as any)?.items ?? []).filter((item: any) => !item.readAt).length;
  const refreshProjects = () => projectsQuery.refetch();

  if (projectRouteId) return <ProjectWorkspace projectId={projectRouteId} onRefresh={refreshProjects} />;
  if (taskRouteId) return <div className="min-h-full bg-background"><TaskDetailDialog task={{ id: taskRouteId }} open={true} onOpenChange={() => navigate("/work/my-tasks")} onRefresh={() => myTasksQuery.refetch()} /></div>;

  return <div className="mx-auto max-w-7xl px-4 py-5 sm:px-6"><PageHeader title="Projects & Plans" subtitle="A single work-management layer for teams, projects, tasks, portfolios, and intake workflows" actions={<div className="flex flex-wrap gap-2"><Button variant="outline" size="sm" onClick={() => setTeamDialog(true)}><Users className="mr-1 h-4 w-4" />New team</Button><Button variant="outline" size="sm" onClick={() => setGlobalSearchOpen(true)}><Search className="mr-1 h-4 w-4" />Search<span className="ml-2 hidden rounded border border-border px-1 text-[10px] text-muted-foreground sm:inline">⌘K</span></Button><Button size="sm" onClick={() => setProjectDialog(true)}><Plus className="mr-1 h-4 w-4" />New project</Button></div>} /><div className="mb-6 border-b border-border pb-3"><p className="text-sm font-medium text-muted-foreground">{homeTab === "projects" ? "All accessible projects" : homeTab === "my_tasks" ? "Tasks assigned to you" : homeTab === "inbox" ? "Project notifications" : "Portfolio workspaces"}</p></div>{homeTab === "projects" && <section><div className="mb-4 flex flex-col gap-3 sm:flex-row"><div className="relative flex-1"><Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" /><Input className="pl-9" placeholder="Search projects…" value={search} onChange={event => setSearch(event.target.value)} /></div><div className="flex items-center gap-2 text-xs text-muted-foreground"><ShieldCheck className="h-4 w-4" />Permission-aware workspace</div></div>{projectsQuery.isLoading ? <div className="py-20 text-center text-sm text-muted-foreground">Loading projects…</div> : projects.length ? <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{projects.map((project: any) => { const total = project.taskCounts?.total ?? 0; const complete = project.taskCounts?.completed ?? 0; const progress = total ? Math.round((complete / total) * 100) : 0; return <button key={project.id} onClick={() => navigate(`/work/projects/${project.id}/${project.defaultView || "list"}`)} className="group rounded-xl border border-border bg-card p-4 text-left shadow-sm transition hover:-translate-y-0.5 hover:border-primary/50 hover:shadow-md"><div className="flex items-start justify-between gap-3"><div className="min-w-0"><div className="flex items-center gap-2"><span className="h-2.5 w-2.5 rounded-full" style={{ backgroundColor: project.color || "#14b8a6" }} /><p className="truncate font-semibold">{project.name}</p></div><p className="mt-1 truncate text-xs text-muted-foreground">{project.teamName || "Independent project"}</p></div><Badge variant="outline" className="gap-1 text-[10px]">{viewMeta[project.defaultView as ProjectView]?.icon}{viewMeta[project.defaultView as ProjectView]?.label || "List"}</Badge></div><div className="mt-5"><div className="mb-1 flex justify-between text-xs text-muted-foreground"><span>{complete}/{total} tasks</span><span>{progress}%</span></div><div className="h-1.5 overflow-hidden rounded-full bg-muted"><div className="h-full bg-primary" style={{ width: `${progress}%` }} /></div></div><div className="mt-4 flex items-center justify-between text-xs text-muted-foreground"><span>{project.ownerName || "No owner"}</span><span>{project.dueOn ? `Due ${format(new Date(project.dueOn), "MMM d")}` : "No target date"}</span></div></button>; })}</div> : <div className="rounded-xl border border-dashed border-border py-20 text-center"><FolderKanban className="mx-auto mb-3 h-10 w-10 text-muted-foreground" /><h2 className="font-semibold">Create the first structured project</h2><p className="mx-auto mt-1 max-w-md text-sm text-muted-foreground">Projects support sections, multi-homed tasks, collaborative activity, custom fields, multiple views, templates, forms, and rules.</p><Button className="mt-4" onClick={() => setProjectDialog(true)}><Plus className="mr-1 h-4 w-4" />Create project</Button></div>}</section>}{homeTab === "my_tasks" && <section className="rounded-xl border border-border bg-card"><div className="flex items-center justify-between border-b border-border px-4 py-3"><div><h2 className="font-semibold">{showDelegated ? "Delegated work" : "My tasks"}</h2><span className="text-xs text-muted-foreground">{showDelegated ? "Tasks you assigned to other people" : "Cross-project tasks assigned to you"}</span></div><Button variant="outline" size="sm" onClick={() => setShowDelegated(value => !value)}>{showDelegated ? "My tasks" : "Delegated"}</Button></div>{visibleMyTasks.length ? <div>{visibleMyTasks.map((task: any) => <button key={task.id} onClick={() => navigate(`/work/tasks/${task.id}`)} className="flex w-full items-center gap-3 border-b border-border px-4 py-3 text-left last:border-0 hover:bg-muted/40"><Circle className="h-4 w-4 text-muted-foreground" /><div className="min-w-0 flex-1"><p className="truncate text-sm font-medium">{task.name}</p><p className="text-xs text-muted-foreground">{task.assigneeName ? `Assigned to ${task.assigneeName} · ` : ""}{task.dueOn ? `Due ${format(new Date(task.dueOn), "MMM d, yyyy")}` : "No due date"}</p></div><Badge variant="outline" className="capitalize">{task.completionStatus}</Badge></button>)}</div> : <div className="py-16 text-center"><ListTodo className="mx-auto mb-2 h-8 w-8 text-muted-foreground" /><p className="text-sm text-muted-foreground">{showDelegated ? "Tasks you assign to others will appear here." : "Tasks assigned to you will appear here across all projects."}</p></div>}</section>}{homeTab === "inbox" && <section className="rounded-xl border border-border bg-card"><div className="flex items-center justify-between border-b border-border px-4 py-3"><h2 className="font-semibold">Inbox</h2><Button variant="ghost" size="sm" onClick={() => { const ids = ((inboxQuery.data as any)?.items ?? []).filter((item: any) => !item.readAt).map((item: any) => item.id); if (ids.length) markRead.mutate({ ids, read: true }); }}>Mark all read</Button></div>{((inboxQuery.data as any)?.items ?? []).length ? <div>{((inboxQuery.data as any)?.items ?? []).map((item: any) => <button key={item.id} onClick={() => { if (!item.readAt) markRead.mutate({ ids: [item.id], read: true }); if (item.taskId) navigate(`/work/tasks/${item.taskId}`); else if (item.projectId) navigate(`/work/projects/${item.projectId}/overview`); }} className={cn("flex w-full items-start gap-3 border-b border-border px-4 py-3 text-left last:border-0 hover:bg-muted/40", !item.readAt && "bg-primary/[0.03]")}><Bell className="mt-0.5 h-4 w-4 shrink-0 text-primary" /><div className="min-w-0 flex-1"><p className="text-sm font-medium">{item.title}</p>{item.body && <p className="mt-0.5 truncate text-xs text-muted-foreground">{item.body}</p>}<p className="mt-1 text-xs text-muted-foreground">{format(new Date(item.createdAt), "MMM d, h:mm a")}</p></div>{!item.readAt && <span className="mt-1 h-2 w-2 rounded-full bg-primary" />}</button>)}</div> : <div className="py-16 text-center"><Inbox className="mx-auto mb-2 h-8 w-8 text-muted-foreground" /><p className="text-sm text-muted-foreground">Mentions, assignments, and project activity will appear here.</p></div>}</section>}{homeTab === "portfolios" && <section><div className="mb-4 flex gap-2"><Input value={newPortfolio} onChange={event => setNewPortfolio(event.target.value)} placeholder="New portfolio name" /><Button onClick={() => { if (newPortfolio.trim()) createPortfolio.mutate({ name: newPortfolio.trim() }, { onSuccess: () => setNewPortfolio("") }); }} disabled={!newPortfolio.trim() || createPortfolio.isPending}><Plus className="mr-1 h-4 w-4" />Create portfolio</Button></div>{portfoliosQuery.isLoading ? <div className="py-16 text-center text-sm text-muted-foreground">Loading portfolios…</div> : (portfoliosQuery.data as any[])?.length ? <div className="grid gap-3 md:grid-cols-2 lg:grid-cols-3">{(portfoliosQuery.data as any[]).map(portfolio => <div className="cursor-pointer rounded-xl border border-border bg-card p-4 transition hover:border-primary/50" key={portfolio.id} onClick={() => setSelectedPortfolioId(portfolio.id)}><BriefcaseBusiness className="mb-3 h-5 w-5 text-primary" /><p className="font-semibold">{portfolio.name}</p><p className="mt-1 text-xs text-muted-foreground">{portfolio.privacy === "public_to_workspace" ? "Workspace portfolio" : "Member-only portfolio"}</p></div>)}</div> : <div className="rounded-xl border border-dashed border-border py-16 text-center"><BriefcaseBusiness className="mx-auto mb-3 h-8 w-8 text-muted-foreground" /><p className="font-semibold">No portfolios yet</p><p className="mt-1 text-sm text-muted-foreground">Use portfolios to roll up projects or create property-level project bundles.</p></div>}</section>}{homeTab === "portfolios" && selectedPortfolioId && <section className="mt-6 rounded-xl border border-border bg-card p-4"><div className="mb-3 flex items-center justify-between"><div><h2 className="font-semibold">Portfolio projects</h2><p className="text-xs text-muted-foreground">Add or remove projects without changing project access.</p></div><Button variant="ghost" size="sm" onClick={() => setSelectedPortfolioId(null)}>Close</Button></div><div className="mb-4 flex gap-2"><select className="h-9 flex-1 rounded-md border border-input bg-background px-3 text-sm" value={portfolioProjectId} onChange={event => setPortfolioProjectId(event.target.value)}><option value="">Select a project…</option>{projects.filter((project: any) => !(portfolioItemsQuery.data as any[] ?? []).some(item => item.projectId === project.id)).map((project: any) => <option key={project.id} value={project.id}>{project.name}</option>)}</select><Button size="sm" disabled={!portfolioProjectId || addPortfolioProject.isPending} onClick={() => addPortfolioProject.mutate({ portfolioId: selectedPortfolioId, projectId: Number(portfolioProjectId) })}>Add project</Button></div>{portfolioItemsQuery.isLoading ? <p className="py-4 text-sm text-muted-foreground">Loading portfolio projects…</p> : (portfolioItemsQuery.data as any[] ?? []).length ? <div className="space-y-2">{(portfolioItemsQuery.data as any[]).map(item => <div key={item.id} className="flex items-center justify-between rounded border border-border px-3 py-2 text-sm"><span>{item.projectName || item.childPortfolioName || "Untitled item"}</span><Button variant="ghost" size="sm" onClick={() => removePortfolioItem.mutate({ portfolioId: selectedPortfolioId, itemId: item.id })}>Remove</Button></div>)}</div> : <p className="py-4 text-sm text-muted-foreground">No projects in this portfolio yet.</p>}</section>}<ProjectCreateDialog open={projectDialog} onOpenChange={setProjectDialog} teams={(teamsQuery.data as any[]) ?? []} onCreated={id => { refreshProjects(); navigate(`/work/projects/${id}/list`); }} /><TeamCreateDialog open={teamDialog} onOpenChange={setTeamDialog} onCreated={() => teamsQuery.refetch()} /><Dialog open={globalSearchOpen} onOpenChange={setGlobalSearchOpen}><DialogContent className="sm:max-w-xl"><DialogHeader><DialogTitle>Search work</DialogTitle><DialogDescription>Find projects and tasks that you can access.</DialogDescription></DialogHeader><div className="relative"><Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" /><Input autoFocus className="pl-9" value={globalSearch} onChange={event => setGlobalSearch(event.target.value)} placeholder="Search projects and tasks…" /></div><div className="max-h-72 overflow-y-auto">{globalSearch.trim().length > 1 ? (globalResultsQuery.data as any[])?.length ? (globalResultsQuery.data as any[]).map(result => <button key={`${result.type}-${result.id}`} className="flex w-full items-center gap-3 border-b border-border px-2 py-3 text-left hover:bg-muted" onClick={() => { setGlobalSearchOpen(false); navigate(result.type === "project" ? `/work/projects/${result.id}/list` : `/work/tasks/${result.id}`); }}><span className="rounded bg-muted p-1.5">{result.type === "project" ? <FolderKanban className="h-3.5 w-3.5" /> : <ListTodo className="h-3.5 w-3.5" />}</span><div><p className="text-sm font-medium">{result.name}</p><p className="text-xs capitalize text-muted-foreground">{result.type}</p></div></button>) : <p className="py-8 text-center text-sm text-muted-foreground">No matching work found.</p> : <p className="py-8 text-center text-sm text-muted-foreground">Enter at least two characters to search.</p>}</div></DialogContent></Dialog></div>;
}
